insert into modules (id, name, description, position_type, default_order) values
  ('mod-standing', 'Standing & Takedowns', 'Takedowns, throws, and guard pulls from the feet.', 'standing', 1),
  ('mod-passing', 'Guard Passing', 'Passing the legs to establish top control.', 'passing', 2),
  ('mod-side', 'Side Control Battle', 'Side control, knee-on-belly, north-south and their escapes.', 'side', 3),
  ('mod-mount', 'Mount Battle', 'Mount control, attacks, and escapes.', 'mount', 4),
  ('mod-back', 'Back Battle', 'Back control, back takes, and back escapes.', 'back', 5),
  ('mod-guard', 'Guard Battle', 'Bottom guard: sweeps, retention, and guard submissions.', 'guard', 6),
  ('mod-legs', 'Leg Locks', 'Leg entanglements and lower-body submissions.', 'legs', 7),
  ('mod-subs', 'Submissions', 'Chokes and joint locks not tied to a single position.', 'submission', 8),
  ('mod-concepts', 'Concepts', 'Principles and frameworks that cut across positions.', 'concept', 9),
  ('mod-drills', 'Drills', 'Solo and partner movement drills.', 'drill', 10)
insert into techniques (id, number, category, type, name, slug, description, complexity, key_details, ruleset, context, leg_lock_tier, wrestling_dependency, default_module_id) values
  ('tech-001', 1, 'Escape', 'Mount Escape', 'Bridge & Roll (Upa)', 'bridge-roll-upa', 'Escape from full mount by bridging explosively and rolling the opponent over when they post a hand or foot.', 'Beginner', 'Trap arm and same-side foot before bridging. Common error: bridging without trapping.', 'Both', 'Self-Defense', 'None', false, 'mod-mount'),
  ('tech-002', 2, 'Escape', 'Mount Escape', 'Elbow-Knee Escape (Shrimp)', 'elbow-knee-escape-shrimp', 'Escape mount by shrimping hips out and recovering guard by inserting knee as a frame.', 'Beginner', 'Drive elbow to knee simultaneously. Error: shrimping without creating the frame first.', 'Both', 'Both', 'None', false, 'mod-mount'),
  ('tech-003', 3, 'Escape', 'Mount Escape', 'Trap & Roll (Cross Collar)', 'trap-roll-cross-collar', 'When opponent grabs collar, use their grip against them to execute bridge and roll.', 'Beginner', 'Works when opponent has stiff straight arms. Trap wrist and elbow.', 'Gi', 'Self-Defense', 'None', false, 'mod-mount'),
  ('tech-004', 4, 'Escape', 'Mount Escape', 'High Mount Escape', 'high-mount-escape', 'Escape when opponent rides high (near armpits) by using frames and underhook to recover half guard.', 'Intermediate', 'Frame on hip and push to create space. Danger zone for chokes — stay tight.', 'Both', 'Both', 'None', false, 'mod-mount'),
  ('tech-005', 5, 'Escape', 'Side Control Escape', 'Frame & Recover Guard', 'frame-recover-guard', 'Use forearm frames to create space and shrimp hips to recover full or half guard.', 'Beginner', 'Frame on chin/hip — not throat. Shrimp toward opponent, not away.', 'Both', 'Both', 'None', false, 'mod-side'),
  ('tech-006', 6, 'Escape', 'Side Control Escape', 'Underhook Roll to Knees', 'underhook-roll-to-knees', 'Secure underhook and bridge to roll to knees, then stand or take back position.', 'Beginner', 'Get underhook before bridging. Error: going to knees without underhook secured.', 'Both', 'Both', 'None', false, 'mod-side'),
  ('tech-007', 7, 'Escape', 'Side Control Escape', 'Ghost Escape (Running Man)', 'ghost-escape-running-man', 'Spin under opponent''s arm to recover guard by turning away and reinserting legs.', 'Intermediate', 'Requires hip flexibility and timing. Best when opponent reaches for far arm.', 'Both', 'Sport', 'None', false, 'mod-side'),
  ('tech-008', 8, 'Escape', 'Back Escape', 'Seatbelt Strip & Roll Under', 'seatbelt-strip-roll-under', 'Strip the seatbelt grip and roll under opponent to come out the front into guard or half guard.', 'Beginner', 'Two-on-one the choking arm first. Never roll the direction opponent wants.', 'Both', 'Both', 'None', false, 'mod-back'),
  ('tech-009', 9, 'Escape', 'Back Escape', 'Seat Belt Strip & Stand', 'seat-belt-strip-stand', 'Strip seatbelt, post foot on mat, and stand up to remove hooks.', 'Intermediate', 'Use when hooks are shallow. Slam hips back to break hooks.', 'Both', 'Both', 'None', false, 'mod-back'),
  ('tech-010', 10, 'Escape', 'Headlock Escape', 'Trap & Roll from Headlock', 'trap-roll-from-headlock', 'When caught in side headlock, trap arm, bridge, and roll opponent over.', 'Beginner', 'Classic self-defense escape. Shoot hips toward opponent''s legs while bridging.', 'Both', 'Self-Defense', 'None', false, 'mod-side'),
  ('tech-011', 11, 'Escape', 'Turtle Escape', 'Granby Roll', 'granby-roll', 'Invert under opponent''s pressure to recover guard from turtle position.', 'Intermediate', 'Roll over far shoulder. Timing: when opponent reaches around for hook.', 'Both', 'Both', 'None', false, 'mod-back'),
  ('tech-012', 12, 'Escape', 'Knee on Belly Escape', 'Shrimp & Recover Guard', 'shrimp-recover-guard', 'Shrimp away from knee pressure while framing on the knee to recover guard.', 'Beginner', 'Push the knee as you shrimp. Error: shrimping without addressing the knee.', 'Both', 'Both', 'None', false, 'mod-side'),
  ('tech-013', 13, 'Sweep', 'Closed Guard Sweep', 'Hip Bump Sweep', 'hip-bump-sweep', 'Sit up and bump hips into opponent while controlling their arm to sweep them sideways.', 'Beginner', 'Sit up explosively. Error: pushing rather than bumping. Chains well into kimura.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-014', 14, 'Sweep', 'Closed Guard Sweep', 'Scissor Sweep', 'scissor-sweep', 'Use crossed legs like scissors — one shin on belly, one knee pulling — to sweep opponent.', 'Beginner', 'Pull-push: pull sleeve, push on hip. Keep connection tight. Error: opening guard too early.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-015', 15, 'Sweep', 'Closed Guard Sweep', 'Flower Sweep (Pendulum)', 'flower-sweep-pendulum', 'Swing legs like a pendulum while controlling collar and arm to sweep opponent over.', 'Intermediate', 'Swing both legs in same arc simultaneously. High success vs. posturing opponents.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-016', 16, 'Sweep', 'Closed Guard Sweep', 'Kimura Sweep', 'kimura-sweep', 'Use kimura grip on wrist to unbalance and sweep opponent when hip bump is defended.', 'Intermediate', 'Chains naturally from hip bump. If sweep fails, finish kimura on the ground.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-017', 17, 'Sweep', 'Butterfly Guard Sweep', 'Basic Butterfly Sweep', 'basic-butterfly-sweep', 'From butterfly guard, use hooks and underhook to elevate and sweep opponent to the side.', 'Beginner', 'Get underhook on sweeping side. Error: no underhook — opponent posts and blocks.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-018', 18, 'Sweep', 'Butterfly Guard Sweep', 'Hook Sweep (Elevator)', 'hook-sweep-elevator', 'Use butterfly hook to elevate opponent''s leg while pulling their arm to sweep.', 'Beginner', 'Hook must be deep (under thigh, not calf). Pull elbow to your hip, not up.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-019', 19, 'Sweep', 'Butterfly Guard Sweep', 'Sumi Gaeshi (Judo Back Roll)', 'sumi-gaeshi-judo-back-roll', 'Fall backward and use butterfly hook to throw opponent over your head.', 'Intermediate', 'Works when opponent drives forward aggressively. Commit fully.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-020', 20, 'Sweep', 'Half Guard Sweep', 'Old School Sweep', 'old-school-sweep', 'From half guard, take underhook and single leg to trip opponent and come on top.', 'Beginner', 'Must secure underhook — without it, opponent flattens you. Dog-fight position first.', 'Both', 'Both', 'None', true, 'mod-guard'),
  ('tech-021', 21, 'Sweep', 'Half Guard Sweep', 'Waiter Sweep', 'waiter-sweep', 'From deep half guard, use leg on opponent''s hip as a lever to sweep.', 'Advanced', 'Enter by going underneath; timing when opponent leans forward. Entry is the hard part.', 'Both', 'Sport', 'None', false, 'mod-guard'),
  ('tech-022', 22, 'Sweep', 'Half Guard Sweep', 'Homer Simpson Sweep', 'homer-simpson-sweep', 'Take underhook, then go to knees and push opponent sideways with shoulder pressure.', 'Intermediate', 'Works when opponent posts arm to block Old School. Look for the posted arm.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-023', 23, 'Sweep', 'De La Riva Sweep', 'Basic DLR Sweep (Push)', 'basic-dlr-sweep-push', 'From De La Riva guard, push opponent''s near knee to collapse their base and sweep.', 'Intermediate', 'Control sleeve and push knee inward simultaneously.', 'Both', 'Sport', 'None', false, 'mod-guard'),
  ('tech-024', 24, 'Sweep', 'De La Riva Sweep', 'DLR Back Take', 'dlr-back-take', 'Use De La Riva hook to off-balance opponent and rotate to take the back.', 'Advanced', 'When opponent steps back to clear hook, rotate under and climb to back.', 'Both', 'Sport', 'None', false, 'mod-guard'),
  ('tech-025', 25, 'Sweep', 'Single Leg X Sweep', 'Single Leg X Basic Sweep', 'single-leg-x-basic-sweep', 'From SLX position, extend legs to put opponent on their back while controlling ankle.', 'Intermediate', 'Break opponent''s posture first. Error: sweeping without breaking posture — opponent posts.', 'Both', 'Sport', 'None', false, 'mod-guard'),
  ('tech-026', 26, 'Sweep', 'X Guard Sweep', 'X Guard Tilt', 'x-guard-tilt', 'From full X guard, tilt opponent by extending one leg and pulling the other.', 'Advanced', 'Both legs must be engaged simultaneously. Difficult entry; worth the reward.', 'Both', 'Sport', 'None', false, 'mod-guard'),
  ('tech-027', 27, 'Sweep', 'Spider Guard Sweep', 'Tomahawk Sweep', 'tomahawk-sweep', 'From spider guard, push one arm with foot while pulling the other to off-balance and sweep.', 'Intermediate', 'Gi-specific. Keep both lasso/push connections tight.', 'Gi', 'Sport', 'None', false, 'mod-guard'),
  ('tech-028', 28, 'Sweep', 'Lasso Guard Sweep', 'Lasso Sweep', 'lasso-sweep', 'Use lasso (leg wrapped around opponent''s arm) as anchor to sweep with hip elevation.', 'Advanced', 'Gi-specific. Lasso arm must be fully trapped to prevent posturing.', 'Gi', 'Sport', 'None', false, 'mod-guard'),
  ('tech-029', 29, 'Submission', 'Choke', 'Rear Naked Choke (RNC)', 'rear-naked-choke-rnc', 'Blood choke from back mount: blade of choking arm across throat, lock behind head.', 'Beginner', 'Choke not air choke. Squeeze with forearm & bicep (not hands). Error: grabbing own shoulder instead of bicep.', 'Both', 'Both', 'None', false, 'mod-subs'),
  ('tech-030', 30, 'Submission', 'Choke', 'Guillotine Choke', 'guillotine-choke', 'Head-and-arm choke from guard or standing: blade of arm under throat, squeeze.', 'Beginner', 'High elbow for blood choke. Arm-in variant is easier to get, harder to finish.', 'Both', 'Both', 'None', false, 'mod-subs'),
  ('tech-031', 31, 'Submission', 'Choke', 'Triangle Choke', 'triangle-choke', 'Leg choke from guard: one arm and opponent''s neck trapped inside leg triangle.', 'Beginner', 'Pull head down and cut angle 90 degrees. Error: not angling — straight-on triangle is weak.', 'Both', 'Both', 'None', false, 'mod-subs'),
  ('tech-032', 32, 'Submission', 'Choke', 'Cross Collar Choke', 'cross-collar-choke', 'Gi choke from mount or guard using both collar grips, blades of wrists on carotids.', 'Beginner', 'Gi-specific. Cross arms so knuckles face up. Elbows in as you finish.', 'Gi', 'Both', 'None', false, 'mod-subs'),
  ('tech-033', 33, 'Submission', 'Choke', 'Bow and Arrow Choke', 'bow-and-arrow-choke', 'Gi choke from back: one collar grip, one pants grip, extend body like bow to finish.', 'Intermediate', 'Gi-specific. Most powerful choke in BJJ. Extend hips and pull collar simultaneously.', 'Gi', 'Sport', 'None', false, 'mod-subs'),
  ('tech-034', 34, 'Submission', 'Choke', 'Clock Choke', 'clock-choke', 'Gi choke from turtle/side control: collar grip with arm draped across back.', 'Intermediate', 'Gi-specific. Walk feet in arc (like clock hand) to increase pressure.', 'Gi', 'Sport', 'None', false, 'mod-subs'),
  ('tech-035', 35, 'Submission', 'Choke', 'D''Arce Choke (Brabo)', 'd-arce-choke-brabo', 'Arm triangle variation where choking arm threads through armpit and behind neck.', 'Intermediate', 'Arm goes under armpit, not over. Finish on same side as trapped arm.', 'Both', 'Sport', 'None', false, 'mod-subs'),
  ('tech-036', 36, 'Submission', 'Choke', 'Anaconda Choke', 'anaconda-choke', 'Roll-through variation of D''Arce: arm through armpit, roll opponent over to finish.', 'Advanced', 'Set up from front headlock. Roll toward trapped arm side.', 'Both', 'Sport', 'None', false, 'mod-subs'),
  ('tech-037', 37, 'Submission', 'Choke', 'Arm Triangle (Head-and-Arm)', 'arm-triangle-head-and-arm', 'Press opponent''s arm into their own neck and squeeze with your own head as second blade.', 'Intermediate', 'Clasp on opposite side of trapped arm. Walk hips out to clear opponent''s shoulder.', 'Both', 'Both', 'None', false, 'mod-subs'),
  ('tech-038', 38, 'Submission', 'Choke', 'Ezekiel Choke', 'ezekiel-choke', 'Sleeve-grip choke from mount: one arm through sleeve, other hand braces.', 'Intermediate', 'Gi-specific but has no-gi variation (wrist choke). Works when opponent frames on your chest.', 'Gi', 'Both', 'None', false, 'mod-subs'),
  ('tech-039', 39, 'Submission', 'Choke', 'Peruvian Necktie', 'peruvian-necktie', 'From front headlock: dive head inside, roll over opponent''s back to finish.', 'Advanced', 'Requires precise positioning. Often done from sprawl on single leg attempt.', 'Both', 'Sport', 'None', false, 'mod-subs'),
  ('tech-040', 40, 'Submission', 'Armlock', 'Armbar', 'armbar', 'Hyperextend elbow by trapping arm between legs and raising hips with arm across hip crease.', 'Beginner', 'Pinch knees. Error: feet crossed or thighs loose. Squeeze and extend simultaneously.', 'Both', 'Both', 'None', false, 'mod-subs'),
  ('tech-041', 41, 'Submission', 'Armlock', 'Kimura', 'kimura', 'Figure-four shoulder lock: control wrist with two-on-one and rotate shoulder joint.', 'Beginner', 'Rotate arm toward opponent''s back. Works from guard, side control, north-south.', 'Both', 'Both', 'None', false, 'mod-subs'),
  ('tech-042', 42, 'Submission', 'Armlock', 'Americana (Key Lock)', 'americana-key-lock', 'Figure-four shoulder lock in opposite direction from Kimura, applied from top.', 'Beginner', 'Paint brush motion — wrist goes down, elbow goes up. Common from mount and side control.', 'Both', 'Both', 'None', false, 'mod-subs'),
  ('tech-043', 43, 'Submission', 'Armlock', 'Omoplata', 'omoplata', 'Shoulder lock using legs: leg over shoulder, rotate to pressure shoulder joint.', 'Intermediate', 'Roll opponent to prevent escape. Can sweep if they posture up to defend.', 'Both', 'Sport', 'None', false, 'mod-subs'),
  ('tech-044', 44, 'Submission', 'Armlock', 'Baratoplata', 'baratoplata', 'Inverted omoplata variation targeting shoulder in opposite direction.', 'Expert', 'Rare and technical. Typically entered from failed omoplata or wristlock position.', 'Both', 'Sport', 'None', false, 'mod-subs'),
  ('tech-045', 45, 'Submission', 'Armlock', 'Gogoplata', 'gogoplata', 'Shin-on-throat choke or neck crank using shin from inverted guard.', 'Expert', 'Requires extreme hip flexibility. More setup-intensive than most submissions.', 'Both', 'Sport', 'None', false, 'mod-subs'),
  ('tech-046', 46, 'Submission', 'Wristlock', 'Wristlock (from Guard)', 'wristlock-from-guard', 'Bend opponent''s wrist against its joint when they post or push your body.', 'Intermediate', 'Surprise submission. Best when opponent posts straight arm. Two hands on one wrist.', 'Both', 'Both', 'None', false, 'mod-subs'),
  ('tech-047', 47, 'Submission', 'Leg Lock', 'Straight Ankle Lock', 'straight-ankle-lock', 'Hyperextend ankle by driving forearm blade into Achilles and squeezing.', 'Beginner', 'Heel in armpit, blade on Achilles. Error: squeezing calf instead of Achilles.', 'Both', 'Both', 'Basic', false, 'mod-legs'),
  ('tech-048', 48, 'Submission', 'Leg Lock', 'Inside Heel Hook', 'inside-heel-hook', 'Rotate knee joint by controlling heel and torquing inward from inside ashi garami.', 'Advanced', 'Most dangerous BJJ submission. Control heel with elbow-to-knee connection before rotating.', 'No-Gi', 'Sport', 'Advanced', false, 'mod-legs'),
  ('tech-049', 49, 'Submission', 'Leg Lock', 'Outside Heel Hook', 'outside-heel-hook', 'Rotate knee joint outward from outside ashi garami (411 / honey hole) position.', 'Expert', 'Extremely high injury risk. Tap is fast; damage is permanent. Control position first.', 'No-Gi', 'Sport', 'Advanced', false, 'mod-legs'),
  ('tech-050', 50, 'Submission', 'Leg Lock', 'Kneebar', 'kneebar', 'Hyperextend knee by pressing patella against forearm fulcrum and extending body.', 'Advanced', 'Squeeze thighs like armbar. Hard to finish without full control of leg.', 'Both', 'Sport', 'Advanced', false, 'mod-legs'),
  ('tech-051', 51, 'Submission', 'Leg Lock', 'Calf Slicer (Bicep Slicer)', 'calf-slicer-bicep-slicer', 'Compress calf muscle against shin bone by wedging knee as fulcrum.', 'Advanced', 'Often entered from back takes or opponent turtling. Very painful — taps come fast.', 'Both', 'Sport', 'Advanced', false, 'mod-legs'),
  ('tech-052', 52, 'Submission', 'Leg Lock', 'Toe Hold', 'toe-hold', 'Rotate foot and ankle with figure-four grip targeting ankle and knee ligaments.', 'Intermediate', 'Figure four with palm facing you. Rotate figure eight to apply pressure.', 'Both', 'Sport', 'Basic', false, 'mod-legs'),
  ('tech-053', 53, 'Guard Pass', 'Pressure Pass', 'Knee Slice Pass', 'knee-slice-pass', 'Slice knee diagonally across opponent''s thigh to pass guard to side control.', 'Beginner', 'Keep chest pressure, angle knee down not forward. Finish with hip switch to side control.', 'Both', 'Both', 'None', false, 'mod-passing'),
  ('tech-054', 54, 'Guard Pass', 'Pressure Pass', 'Double Underhook Smash Pass', 'double-underhook-smash-pass', 'Control both legs with underhooks, drive hips forward, and smash to side control.', 'Beginner', 'Flatten opponent''s hips first. Error: letting them re-guard before securing side control.', 'Both', 'Both', 'None', false, 'mod-passing'),
  ('tech-055', 55, 'Guard Pass', 'Pressure Pass', 'Torreando (Bull Fighter)', 'torreando-bull-fighter', 'Control both ankles/pants, redirect legs to the side, and pass to side control.', 'Beginner', 'Works best when opponent has straight legs. Move opponent''s legs, not your body.', 'Both', 'Both', 'None', false, 'mod-passing'),
  ('tech-056', 56, 'Guard Pass', 'Pressure Pass', 'Over-Under Pass', 'over-under-pass', 'One arm over opponent''s leg, one under, drive hips forward to smash through guard.', 'Intermediate', 'Tripod base. Drive forward with hips; error: driving with shoulders.', 'Both', 'Both', 'None', false, 'mod-passing'),
  ('tech-057', 57, 'Guard Pass', 'Pressure Pass', 'Headquarters (HQ) Pass', 'headquarters-hq-pass', 'Knee inside opponent''s guard at 45 degrees, control sleeve and collar, pressure forward.', 'Beginner', 'Start of most modern passing sequences. Controls guard player''s mobility.', 'Both', 'Both', 'None', false, 'mod-passing'),
  ('tech-058', 58, 'Guard Pass', 'Movement Pass', 'Leg Drag Pass', 'leg-drag-pass', 'Drag opponent''s leg across their body to pin it and pass to side control.', 'Intermediate', 'Control ankle and push knee across. Fast pass when opponent opens guard.', 'Both', 'Sport', 'None', false, 'mod-passing'),
  ('tech-059', 59, 'Guard Pass', 'Movement Pass', 'Toreando to Leg Drag Combo', 'toreando-to-leg-drag-combo', 'Redirect legs with toreando, then transition to leg drag when they frame.', 'Intermediate', 'One pass sets up the other. Keep wrist control throughout transition.', 'Both', 'Sport', 'None', false, 'mod-passing'),
  ('tech-060', 60, 'Guard Pass', 'Movement Pass', 'Long Step Pass', 'long-step-pass', 'Step over opponent''s leg with long step and spin to side control.', 'Intermediate', 'Establish grips before stepping. Error: stepping without controlling hips first.', 'Both', 'Both', 'None', false, 'mod-passing'),
  ('tech-061', 61, 'Guard Pass', 'De La Riva Counter', 'Knee Slice vs. DLR', 'knee-slice-vs-dlr', 'Address DLR hook by cutting knee past it and slicing to side control.', 'Intermediate', 'Post hand on mat, swing knee backward past hook before slicing forward.', 'Both', 'Sport', 'None', false, 'mod-passing'),
  ('tech-062', 62, 'Guard Pass', 'De La Riva Counter', 'Toreando vs. DLR', 'toreando-vs-dlr', 'Clear DLR hook by pushing ankle away and stepping to the side to pass.', 'Intermediate', 'Speed-dependent. Good when opponent''s DLR is shallow.', 'Both', 'Sport', 'None', false, 'mod-passing'),
  ('tech-063', 63, 'Guard Pass', 'Leg Lock Entry', 'Pass to Leg Lock (50/50 Entry)', 'pass-to-leg-lock-50-50-entry', 'When pass is blocked, drop into 50/50 to attack legs instead of passing.', 'Advanced', 'Guard player''s counter creates leg lock entry. Know leg lock game before using this.', 'Both', 'Sport', 'Advanced', false, 'mod-legs'),
  ('tech-064', 64, 'Takedown', 'Leg Attack', 'Double Leg Takedown', 'double-leg-takedown', 'Drive into opponent''s hips, grab both legs, and drive forward to bring them down.', 'Beginner', 'Level change first, then penetration step. Error: reaching without level change.', 'Both', 'Both', 'None', true, 'mod-standing'),
  ('tech-065', 65, 'Takedown', 'Leg Attack', 'Single Leg Takedown', 'single-leg-takedown', 'Control one leg and finish by lifting, running the pipe, or trip.', 'Beginner', 'Three finishes: lift, run the pipe, outside trip. Head inside for safety.', 'Both', 'Both', 'None', true, 'mod-standing'),
  ('tech-066', 66, 'Takedown', 'Leg Attack', 'Double Leg to Single Leg', 'double-leg-to-single-leg', 'Start double leg, shift to single when opponent sprawls or defends.', 'Intermediate', 'Adaptability drill. Practice the transition reaction, not just both moves separately.', 'Both', 'Both', 'None', true, 'mod-standing'),
  ('tech-067', 67, 'Takedown', 'Hip Throw', 'Osoto Gari (Outside Reap)', 'osoto-gari-outside-reap', 'Step outside opponent''s leg and reap backwards while pushing head.', 'Beginner', 'Judo throw. Off-balance (kuzushi) before reaping. Plant foot close to theirs.', 'Both', 'Both', 'None', false, 'mod-standing'),
  ('tech-068', 68, 'Takedown', 'Hip Throw', 'Seoi Nage (Shoulder Throw)', 'seoi-nage-shoulder-throw', 'Turn in under opponent''s arm and throw them over your shoulder/back.', 'Intermediate', 'Judo throw. Drop level dramatically on entry. Works best when opponent pulls you in.', 'Both', 'Both', 'None', false, 'mod-standing'),
  ('tech-069', 69, 'Takedown', 'Hip Throw', 'Hip Toss (O Goshi)', 'hip-toss-o-goshi', 'Classic hip throw: encircle opponent''s waist, load onto hip, throw.', 'Beginner', 'Hip must get lower than opponent''s center of gravity. Error: not loading the hip.', 'Both', 'Both', 'None', false, 'mod-standing'),
  ('tech-070', 70, 'Takedown', 'Foot Sweep', 'Kouchi Gari (Inside Foot Sweep)', 'kouchi-gari-inside-foot-sweep', 'Sweep opponent''s near foot inward while pushing them backward.', 'Intermediate', 'Timing-based: sweep as their weight shifts to the foot you''re sweeping.', 'Both', 'Both', 'None', false, 'mod-standing'),
  ('tech-071', 71, 'Takedown', 'Foot Sweep', 'Ouchi Gari (Major Inside Reap)', 'ouchi-gari-major-inside-reap', 'Hook opponent''s leg from inside and reap backward while pushing body.', 'Intermediate', 'Judo throw. Entry from collar-sleeve grip. Often sets up Seoi Nage.', 'Both', 'Both', 'None', false, 'mod-standing'),
  ('tech-072', 72, 'Takedown', 'Wrestling', 'Arm Drag to Back', 'arm-drag-to-back', 'Control opponent''s arm and drag it across to step behind and take the back.', 'Intermediate', 'Two-on-one the arm, step through with far leg. Works from pummeling or collar tie.', 'Both', 'Both', 'None', true, 'mod-standing'),
  ('tech-073', 73, 'Takedown', 'Wrestling', 'Snap Down to Front Headlock', 'snap-down-to-front-headlock', 'Snap opponent''s head down and apply front headlock to create submissions or takedowns.', 'Beginner', 'Works when opponent has head high. Drive head down with pushing-pulling motion.', 'Both', 'Both', 'None', true, 'mod-standing'),
  ('tech-074', 74, 'Takedown', 'Wrestling', 'Collar Tie to Knee Tap', 'collar-tie-to-knee-tap', 'From collar tie, reach for far knee and tap forward while pulling head.', 'Intermediate', 'Works when opponent steps forward. Timing with their step is crucial.', 'Both', 'Both', 'None', true, 'mod-standing'),
  ('tech-075', 75, 'Takedown', 'Guard Pull', 'Guard Pull to Butterfly', 'guard-pull-to-butterfly', 'Sit to guard and immediately secure butterfly hooks before opponent can establish base.', 'Beginner', 'Establish grips before sitting. Error: sitting with no grips — opponent smashes pass immediately.', 'Both', 'Sport', 'None', false, 'mod-standing'),
  ('tech-076', 76, 'Takedown', 'Guard Pull', 'Jump to Closed Guard', 'jump-to-closed-guard', 'Jump closed guard onto standing opponent.', 'Beginner', 'Sport technique. Pull collar and sleeve before jumping. Risky if timed wrong.', 'Both', 'Sport', 'None', false, 'mod-standing'),
  ('tech-077', 77, 'Control', 'Top Position', 'Side Control', 'side-control', 'Dominant top position: perpendicular to opponent, cross-body weight, controlling hips and head.', 'Beginner', 'Chest-to-chest. Far arm under head, near arm blocking hip. Error: hips too high.', 'Both', 'Both', 'None', false, 'mod-side'),
  ('tech-078', 78, 'Control', 'Top Position', 'Mount', 'mount', 'Straddle opponent''s torso for dominant top control, knees squeezing hips.', 'Beginner', 'Stay low (technical mount) or high. Error: sitting up — gives escape room.', 'Both', 'Both', 'None', false, 'mod-mount'),
  ('tech-079', 79, 'Control', 'Top Position', 'Technical Mount', 'technical-mount', 'Partial mount with one foot hooked under opponent''s hip for better control.', 'Intermediate', 'More stable than full mount against good escapes. Hips angled.', 'Both', 'Both', 'None', false, 'mod-mount'),
  ('tech-080', 80, 'Control', 'Top Position', 'Back Mount', 'back-mount', 'Take opponent''s back with seatbelt grip and both hooks inside their thighs.', 'Beginner', 'Over-under seatbelt; hooks point inward not outward. Error: crossed feet — easy foot lock.', 'Both', 'Both', 'None', false, 'mod-back'),
  ('tech-081', 81, 'Control', 'Top Position', 'Knee on Belly', 'knee-on-belly', 'Place knee on opponent''s stomach for mobile, pressuring control between moves.', 'Beginner', 'Drive shin, not kneecap. Far collar and sleeve grips. Transition position — don''t stay long.', 'Both', 'Both', 'None', false, 'mod-side'),
  ('tech-082', 82, 'Control', 'Top Position', 'North-South', 'north-south', 'Head-to-feet position across opponent: good for transitions, kimura, north-south choke.', 'Intermediate', 'Weight on chest, not head. Transition hub — kimura, choke, or back take.', 'Both', 'Both', 'None', false, 'mod-side'),
  ('tech-083', 83, 'Control', 'Guard', 'Closed Guard', 'closed-guard', 'Legs locked around opponent''s waist controlling their posture and movement.', 'Beginner', 'Break posture before attacking. Error: attacking with opponent''s posture intact.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-084', 84, 'Control', 'Guard', 'Half Guard', 'half-guard', 'One leg trapped between defender''s legs; both guard and top positions.', 'Beginner', 'Guard player seeks underhook; top player seeks to flatten and pass.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-085', 85, 'Control', 'Guard', 'Butterfly Guard', 'butterfly-guard', 'Seated guard with both feet as hooks on opponent''s inner thighs.', 'Beginner', 'Sit upright. Control with hooks and underhook. Error: leaning back — lose hooks.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-086', 86, 'Control', 'Guard', 'De La Riva Guard', 'de-la-riva-guard', 'One leg hooked around outside of opponent''s near leg with ankle control.', 'Intermediate', 'Outside hook + wrist control + collar/sleeve. Platform for sweeps and back takes.', 'Both', 'Sport', 'None', false, 'mod-guard'),
  ('tech-087', 87, 'Control', 'Guard', 'Single Leg X Guard', 'single-leg-x-guard', 'Sit into opponent''s leg with thigh on their thigh, ankle trapped between arms.', 'Intermediate', 'Control ankle with both hands. Break their posture before entering.', 'Both', 'Sport', 'None', false, 'mod-guard'),
  ('tech-088', 88, 'Control', 'Guard', 'X Guard (Full)', 'x-guard-full', 'Both legs used as hooks on opponent''s legs, seated underneath them.', 'Advanced', 'Requires timing to enter cleanly. Very mobile — many sweep options.', 'Both', 'Sport', 'None', false, 'mod-guard'),
  ('tech-089', 89, 'Control', 'Guard', 'Spider Guard', 'spider-guard', 'Both feet on opponent''s biceps/forearms while controlling sleeves.', 'Intermediate', 'Gi-specific. Maintain tension — push and pull simultaneously with feet and hands.', 'Gi', 'Sport', 'None', false, 'mod-guard'),
  ('tech-090', 90, 'Control', 'Guard', 'Lasso Guard', 'lasso-guard', 'One leg wraps around opponent''s arm and through their armpit for control.', 'Advanced', 'Gi-specific. Lasso arm completely immobilized. Entry from spider guard.', 'Gi', 'Sport', 'None', false, 'mod-guard'),
  ('tech-091', 91, 'Control', 'Guard', '50/50 Guard', '50-50-guard', 'Both athletes'' legs intertwined symmetrically; often a leg lock battle.', 'Advanced', 'Equal position — requires leg lock knowledge to attack or escape safely.', 'Both', 'Sport', 'Advanced', false, 'mod-legs'),
  ('tech-092', 92, 'Control', 'Guard', 'Ashi Garami (Single Leg X Entry)', 'ashi-garami-single-leg-x-entry', 'One-leg entanglement used as leg lock platform.', 'Intermediate', 'Inside ashi for inside heel hook; outside ashi for outside heel hook. Position first.', 'Both', 'Sport', 'Basic', false, 'mod-legs'),
  ('tech-093', 93, 'Control', 'Guard', 'Saddle (Outside Ashi / 411)', 'saddle-outside-ashi-411', 'Both legs entangled for outside heel hook attacks.', 'Advanced', 'Most dangerous entry position. Control both legs before attacking.', 'Both', 'Sport', 'Advanced', false, 'mod-legs'),
  ('tech-094', 94, 'Transition', 'Back Take', 'Back Take from Turtle', 'back-take-from-turtle', 'Take opponent''s back when they are in turtle position by securing seatbelt and inserting hooks.', 'Beginner', 'Chest-to-back first, then insert hooks one at a time. Error: going for hooks before seatbelt.', 'Both', 'Both', 'None', false, 'mod-back'),
  ('tech-095', 95, 'Transition', 'Back Take', 'Back Take from Crucifix', 'back-take-from-crucifix', 'From side control, trap arm and leg to take back with armlock threat.', 'Advanced', 'Trap far arm between your legs. Adds armbar and choke threats simultaneously.', 'Both', 'Sport', 'None', false, 'mod-back'),
  ('tech-096', 96, 'Transition', 'Back Take', 'Arm Drag from Guard', 'arm-drag-from-guard', 'Drag opponent''s arm from guard to rotate and climb to back.', 'Intermediate', 'Two-on-one drag, rotate hips 90 degrees, climb up to hooks.', 'Both', 'Both', 'None', true, 'mod-back'),
  ('tech-097', 97, 'Transition', 'Back Take', 'Berimbolo', 'berimbolo', 'Invert under opponent''s hips from DLR/lapel guard, spin through to take back.', 'Advanced', 'Requires good inversions. Entry from DLR when opponent stands to pass.', 'Gi', 'Sport', 'None', false, 'mod-back'),
  ('tech-098', 98, 'Transition', 'Side Control to Mount', 'Mount from Side Control (Knee Through)', 'mount-from-side-control-knee-through', 'Transition from side control to mount by sliding knee across belly to mount.', 'Beginner', 'Isolate far arm first. Slide knee while maintaining chest connection.', 'Both', 'Both', 'None', false, 'mod-mount'),
  ('tech-099', 99, 'Transition', 'Side Control to Mount', 'Step Over Mount', 'step-over-mount', 'Walk foot over opponent''s body from side control to reach mount.', 'Beginner', 'Control head and hip. Walk foot over slowly maintaining pressure.', 'Both', 'Both', 'None', false, 'mod-mount'),
  ('tech-100', 100, 'Transition', 'Mount to Back', 'Take Back from Mount', 'take-back-from-mount', 'When opponent turns into you to escape mount, reward with back take.', 'Intermediate', 'Stay patient — wait for turn, then over-under seatbelt and follow.', 'Both', 'Both', 'None', false, 'mod-back'),
  ('tech-101', 101, 'Transition', 'Guard to Takedown', 'Sweep to Top Game', 'sweep-to-top-game', 'Convert any guard sweep into immediate submission attempt or controlled top position.', 'Beginner', 'Conceptual: sweeps are not the end — always look for the finish on top.', 'Both', 'Both', 'None', false, 'mod-standing'),
  ('tech-102', 102, 'Guard Retention', 'Hip Movement', 'Basic Shrimp (Hip Escape)', 'basic-shrimp-hip-escape', 'Extend hips away from opponent to create space and recover guard.', 'Beginner', 'Foundation of BJJ. Shrimp toward opponent, not away. Push with feet too.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-103', 103, 'Guard Retention', 'Hip Movement', 'Granby Roll (Inversion)', 'granby-roll-inversion', 'Roll over shoulder to invert and recover guard when opponent passes.', 'Intermediate', 'Roll over near shoulder. Covers when shrimping is too slow.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-104', 104, 'Guard Retention', 'Framing', 'Knee Shield Half Guard', 'knee-shield-half-guard', 'Use knee as frame/wedge between you and opponent in half guard to prevent flattening.', 'Beginner', 'Knee in opponent''s hip, not belly. Maintain angle.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-105', 105, 'Guard Retention', 'Framing', 'Hip Frame vs. Knee on Belly', 'hip-frame-vs-knee-on-belly', 'Frame on hip with forearm to prevent knee slide or knee on belly.', 'Beginner', 'Elbow on mat, forearm vertical. Error: framing on belly — no leverage.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-106', 106, 'Guard Retention', 'Leg Pummeling', 'Leg Pummel vs. Pass', 'leg-pummel-vs-pass', 'Pummel legs to maintain guard hooks when opponent tries to clear them.', 'Intermediate', 'Active guard retention. Constantly re-engage hooks as they''re cleared.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-107', 107, 'Guard Retention', 'Recovery', 'Recover Guard from Turtle', 'recover-guard-from-turtle', 'From defensive turtle, use granby or sit-out to recover guard.', 'Intermediate', 'Assess which direction opponent is attacking before choosing recovery.', 'Both', 'Both', 'None', false, 'mod-guard'),
  ('tech-108', 108, 'Concept', 'Positional Hierarchy', 'BJJ Positional Hierarchy', 'bjj-positional-hierarchy', 'Understanding the value of positions: back > mount > side control > guard > half guard > bottom.', 'Beginner', 'Guides decision-making in live rolling. Always seek the next better position.', 'Both', 'Both', 'None', false, 'mod-concepts'),
  ('tech-109', 109, 'Concept', 'Posture', 'Posture Control in Guard', 'posture-control-in-guard', 'Breaking and maintaining posture in guard — foundational for attacks and defense.', 'Beginner', 'Bottom: break posture to attack. Top: maintain posture to pass. Fundamental game.', 'Both', 'Both', 'None', false, 'mod-concepts'),
  ('tech-110', 110, 'Concept', 'Weight Distribution', 'Base & Weight Distribution', 'base-weight-distribution', 'Understanding how to distribute weight for top control and why frames work as levers.', 'Beginner', 'Distribute weight through chest, not arms. Frames work when perpendicular to force.', 'Both', 'Both', 'None', false, 'mod-concepts'),
  ('tech-111', 111, 'Concept', 'Connection', 'Attachment Points & Grips', 'attachment-points-grips', 'Why grips matter: sleeve, collar, wrist, underhook — each controls different movement vectors.', 'Intermediate', 'No grip = no control. Learn what each grip prevents before learning what it enables.', 'Both', 'Both', 'None', false, 'mod-concepts'),
  ('tech-112', 112, 'Concept', 'Timing', 'Timing vs. Mechanics', 'timing-vs-mechanics', 'The same technique requires either strength OR perfect timing. Timing is the goal.', 'Intermediate', 'Slow partner drilling builds mechanics; live drilling builds timing. Both required.', 'Both', 'Both', 'None', false, 'mod-concepts'),
  ('tech-113', 113, 'Concept', 'Offense', 'Combining Attacks', 'combining-attacks', 'Chaining submissions and sweeps so each defense creates the next opportunity.', 'Intermediate', 'Triangle → armbar → omoplata. Hip bump → kimura. Never one-dimensional.', 'Both', 'Both', 'None', false, 'mod-concepts'),
  ('tech-114', 114, 'Concept', 'Defense', 'Submission Defense Principles', 'submission-defense-principles', 'Don''t panic, find the stack/posture/rotation that relieves pressure before escaping.', 'Beginner', 'Tap early — tapping is information. Ego causes injuries in training.', 'Both', 'Both', 'None', false, 'mod-concepts'),
  ('tech-115', 115, 'Concept', 'Strategy', 'Energy Management', 'energy-management', 'Conserve energy by using position and leverage rather than strength; rest in top positions.', 'Intermediate', 'Top positions are (usually) more restful. Learn to relax when nothing is happening.', 'Both', 'Both', 'None', false, 'mod-concepts'),
  ('tech-116', 116, 'Concept', 'Leg Locks', 'Leg Lock Hierarchy & Safety', 'leg-lock-hierarchy-safety', 'Understanding position-first leg lock game: ashi garami → heel hook → finish.', 'Advanced', 'Position before submission. Heel hooks damage without warning — control first.', 'Both', 'Sport', 'Advanced', false, 'mod-legs'),
  ('tech-117', 117, 'Concept', 'Self Defense', 'Guard on Hard Ground', 'guard-on-hard-ground', 'Why guard pull is disadvantageous outside sport: ground hazards, multiple opponents.', 'Beginner', 'Self-defense lens: prefer takedown and top position. Guard is last resort.', 'Both', 'Self-Defense', 'None', false, 'mod-concepts'),
  ('tech-118', 118, 'Drill', 'Solo', 'Hip Escape (Shrimp) Drill', 'hip-escape-shrimp-drill', 'Continuous shrimping across mat to build hip mobility and muscle memory.', 'Beginner', 'The single most important solo BJJ drill. Do it daily.', 'Both', 'Both', 'None', false, 'mod-drills'),
  ('tech-119', 119, 'Drill', 'Solo', 'Bridge & Roll Drill', 'bridge-roll-drill', 'Explosive bridging motion across mat to build mount escape muscle memory.', 'Beginner', 'Bridge straight up before rolling sideways. Don''t just roll — bridge first.', 'Both', 'Both', 'None', false, 'mod-drills'),
  ('tech-120', 120, 'Drill', 'Solo', 'Technical Stand-Up', 'technical-stand-up', 'From seated, use hand, foot, and opposite shin to stand without exposing back.', 'Beginner', 'Self-defense fundamental. Hand behind you, foot forward, shin blocks, stand.', 'Both', 'Both', 'None', false, 'mod-drills'),
  ('tech-121', 121, 'Drill', 'Solo', 'Forward/Backward Roll', 'forward-backward-roll', 'Basic gymnastic rolls for fluency in inversions essential for berimbolo/Granby.', 'Beginner', 'Safety first: tuck chin. Roll over shoulder, not neck.', 'Both', 'Both', 'None', false, 'mod-drills'),
  ('tech-122', 122, 'Drill', 'Solo', 'Inversion Drill', 'inversion-drill', 'Controlled inverted positions to build comfort for Granby and modern guard.', 'Intermediate', 'Start slow. Tuck chin. Build flexibility before speed.', 'Both', 'Both', 'None', false, 'mod-drills'),
  ('tech-123', 123, 'Drill', 'Partner', 'Pummeling (Underhook Exchange)', 'pummeling-underhook-exchange', 'Rhythmic underhook fighting drill to develop clinch sensitivity and reactions.', 'Beginner', 'Flow, don''t force. Goal: feel the opening, not create it.', 'Both', 'Both', 'None', true, 'mod-drills'),
  ('tech-124', 124, 'Drill', 'Partner', 'Guard Passing vs. Guard Retention', 'guard-passing-vs-guard-retention', 'Specific sparring: one passes, one retains guard — no submissions.', 'Beginner', 'Best way to develop guard and passing simultaneously. Reset when side control achieved.', 'Both', 'Both', 'None', false, 'mod-drills'),
  ('tech-125', 125, 'Drill', 'Partner', 'Positional Sparring (Start in Mount)', 'positional-sparring-start-in-mount', 'One defends mount, one maintains and submits — reset when escape or tap occurs.', 'Beginner', 'Do for all positions. Forces deliberate practice of each position''s specific problems.', 'Both', 'Both', 'None', false, 'mod-drills'),
  ('tech-126', 126, 'Drill', 'Partner', 'Sweep vs. Pass Drill', 'sweep-vs-pass-drill', 'Guard player tries to sweep, top player tries to pass — no submissions.', 'Beginner', 'Develops guard and top game simultaneously with lower injury risk than full sparring.', 'Both', 'Both', 'None', false, 'mod-drills'),
  ('tech-127', 127, 'Drill', 'Partner', 'Leg Lock Entry Drill', 'leg-lock-entry-drill', 'Practice leg lock entries (ashi garami, saddle) without finishing — focus on position.', 'Intermediate', 'Learn position before pressure. Drilling the entry is more valuable than the finish.', 'Both', 'Sport', 'Basic', false, 'mod-legs'),
  ('tech-128', 128, 'Drill', 'Partner', 'Flow Rolling', 'flow-rolling', 'Light, slow sparring focused on movement and technique rather than winning.', 'Beginner', 'Rule: if you use strength, reset. Builds sensitivity and creativity.', 'Both', 'Both', 'None', false, 'mod-drills')
